function table(title,columns,rows,caption){const t=E().createTable({title,columns:columns.map(([key,label])=>({key,label})),rows,caption});t.classList.add('fie-mobile-cards');for(const tr of t.querySelectorAll('tbody tr:not(.fie-expanded)'))Array.from(tr.children).forEach((c,i)=>c.dataset.label=columns[i]?.[1]||'Details');return t;}
let index=null,pending=null,renderSerial=0,readerSerial=0;
async function get(url){if(!/^data\/ui\/(reports|waivers)\/[\w/.-]+\.json$/.test(url))throw Error('Unregistered report path');const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error(`HTTP ${r.status}`);return r.json();}
