function inventory(idx){const box=el('div');if(!idx.inventories.length){box.append(note('No completeness inventory served in this build.'));return box;}const picker=el('select');picker.setAttribute('aria-label','Inventory season');for(const r of idx.inventories)picker.append(el('option','',r.season));const area=el('div');box.append(picker,area);let version=0;const paint=async()=>{const v=++version;area.replaceChildren(note('Loading source inventory…'));try{const ref=idx.inventories.find(x=>x.season===picker.value),x=await get(ref.url);if(v!==version)return;const leagues=x.inventory.leagues||[],league=el('select'),position=el('select');league.setAttribute('aria-label','Inventory league');for(const r of leagues){const o=el('option','',r.league_id||r.id);o.value=r.league_id||r.id;league.append(o);}position.setAttribute('aria-label','Inventory position');for(const p of ['QB','RB','WR','TE'])position.append(el('option','',p));const rowsBox=el('div');area.replaceChildren(note('Recorded inventory states only. Artifact presence, statistical validation and production authorization are independent dimensions.'),league,position,rowsBox);let limit=25;const more=button('Show 25 more dimensions',()=>{limit+=25;rowsPaint();});area.append(more);const rowsPaint=()=>{const r=leagues.find(z=>String(z.league_id||z.id)===league.value);const rows=(r?.cells||[]).filter(c=>c.position===position.value).map(c=>({title:`${c.feature_family} · ${c.dimension}`,family:c.feature_family,dimension:c.dimension,horizon:c.horizon,status:{label:c.state,tone:c.state==='ABSENT'?'blocked':'research'},expanded:[['Decision domain',c.decision_domain],['Blockers',json(c.blockers)],['Source evidence',json(c.evidence)]],advanced:[['League ID',league.value],['Season',ref.season],['Source binding',json(x.source)],['Exact cell',json(c)],['Inventory governance',json(x.inventory.governance)]]}));rowsBox.replaceChildren(table('Completeness dimensions',[['family','Feature family'],['dimension','Dimension'],['horizon','Horizon'],['status','Recorded state']],rows.slice(0,limit),`League ${league.value} · ${ref.season} · ${position.value}`));more.hidden=rows.length<=limit;};league.onchange=()=>{limit=25;rowsPaint();};position.onchange=()=>{limit=25;rowsPaint();};rowsPaint();}catch(e){area.replaceChildren(note(`Inventory unavailable: ${e.message}`));}};picker.onchange=paint;paint();return box;}
async function openLeagueReport(trigger=document.activeElement){const version=++readerSerial,lid=String(S().league?.league_id||'');const box=el('div','fie-league-research-reader');E().openReader({title:'League research report',level:'Basic · league research',context:lid?`League ${lid}`:'No selected league',content:box},trigger);if(!lid){box.append(note('Load a league to open its research report.'));return;}box.append(note('Loading league-scoped research…'));try{const [r,s]=await Promise.all([window.FIEResearchReportService.readiness(),window.FIEResearchReportService.reportSummary()]);if(version!==readerSerial||String(S().league?.league_id||'')!==lid||!$('fieEvidenceReader')?.open)return;box.replaceChildren(note(`League ${lid} · as of ${s.generated_at||s.as_of||s.asof||r.generated_at||r.as_of||r.asof||r.pipeline?.generated_at||'Unavailable'} · research report; canonical app ranking retains its own owner.`));const tabs=el('div','fie-actions'),body=el('div');box.append(tabs,body);const positions=['QB','RB','WR','TE','DST','K',...(s.top?.IDP?['IDP']:[])];const lenses=['Overview',...positions,'Top-100','Sleepers >100'];function paint(lens){tabs.querySelectorAll('button').forEach(b=>{b.setAttribute('aria-pressed',String(b.textContent===lens));});body.replaceChildren();if(lens==='Overview'){const h=s.headline||{},value=v=>v==null?'Unavailable':String(v);body.append(note(`Pipeline: ${value(h.pipeline_status)} · Top-100 values / fades: ${value(h.actionable_top100_positive)} / ${value(h.actionable_top100_negative)} · Sleepers >100: ${value(h.positive_sleepers_gt100)}`));const rows=Object.entries(s.position_models||{}).map(([position,m])=>({title:position,position,production:m.selected_production_model,challenger:m.best_research_challenger,status:{label:m.decision||'Unverified',tone:'research'},expanded:[['Exact scoring',json(m.exact_scoring)],['Target / horizon / sample','Use source details; not inferred from model name']],advanced:[['Position model record',json(m)],['Readiness',json(r)],['League ID',lid]]}));body.append(table('Position model decisions',[['position','Position'],['production','Production model'],['challenger','Research challenger'],['status','Decision']],rows,`League ${lid}`));body.append(details('Advanced · pipeline status and source summary',el('pre','',json({readiness:r,headline:s.headline,report_metadata:s.metadata}))));return;}
 const model=s.position_models?.[lens];if(model)body.append(note(`${lens}: production ${model.selected_production_model??'Unavailable'} · challenger ${model.best_research_challenger??'Unavailable'} · ${model.decision??'Unverified'} · exact scoring ${json(model.exact_scoring)}`));
 const groups=lens==='Top-100'?[['Positive outliers',s.outliers_top100?.positive],['Negative outliers',s.outliers_top100?.negative]]:lens==='Sleepers >100'?['QB','RB','WR','TE'].map(p=>[p,s.sleepers_gt100?.[p]]):[[lens,s.top?.[lens]]];for(const [name,players] of groups){const rows=(players||[]).map(p=>({title:p.name,name:p.name,role:`${p.position||name} · ${p.team||'Unknown'}`,rank:p.position_rank,points:fmt(p.projection_points),expanded:[['Research VORP',fmt(p.vorp)],['ADP',fmt(p.adp)],['Positional rank edge',p.rank_edge_position],['Selected model',p.model_selected],['Horizon','Source-defined research projection; not an archived weekly forecast']],advanced:[['Exact player record',json(p)],['Position model',json(s.position_models?.[p.position||name])],['League ID',lid],['Authority','Research report only; no challenger activation']]}));body.append(table(name+' research players',[['name','Player'],['role','Position / team'],['rank','Position rank'],['points','Research pts']],rows,`League ${lid} · ${lens}`));if(!rows.length)body.append(note('No rows supplied for this lens.'));}}for(const lens of lenses)tabs.append(button(lens,()=>paint(lens)));paint('Overview');
 }catch(e){if(version===readerSerial&&String(S().league?.league_id||'')===lid)box.replaceChildren(note(`Research report unavailable for this league: ${e.message}`));}}
// Original asynchronous research owners keep their tables. Disclose large sections after each render.
function enhanceSummary(host){if(!host||host.dataset.fieLayering==='busy')return;host.dataset.fieLayering='busy';for(const h of [...host.children].filter(x=>x.tagName==='H3')){const d=el('details','fie-weekly-details fie-research-section');const label=h.textContent;d.append(el('summary','',`Expanded · ${label}`));h.before(d);d.append(h);while(d.nextSibling&&!(d.nextSibling.nodeType===1&&['H2','H3','DETAILS'].includes(d.nextSibling.tagName)))d.append(d.nextSibling);}
 for(const d of host.querySelectorAll(':scope > .fie-research-section')){if(d.dataset.basic)continue;d.dataset.basic='1';const basic=el('section','fie-research-basic');basic.append(el('h3','',d.querySelector('summary').textContent.replace('Expanded · ','')));const first=d.querySelector('p,.notice');if(first)basic.append(note(first.textContent));const source=d.querySelector('table');if(source){const preview=el('table');const original=[...source.querySelectorAll('tr')];for(const row of original.slice(0,4)){const tr=el('tr');for(const c of [...row.children].slice(0,4))tr.append(el(c.tagName.toLowerCase(),'',c.textContent));preview.append(tr);}const scroll=el('div','fie-table-scroll');scroll.tabIndex=0;scroll.append(preview);basic.append(scroll,note('Basic · first source rows and columns. Expand for the complete table, qualifications and methods.'));}else basic.append(note('Expand for the source-defined finding and scope.'));d.before(basic);}host.dataset.fieLayering='done';}
function bind(){for(const id of ['m1ResearchSummary','m2ResearchSummary','m3ResearchSummary','m4ResearchSummary','m5ResearchSummary','m6ResearchSummary']){const host=$(id);if(host)new MutationObserver(()=>enhanceSummary(host)).observe(host,{childList:true});}window.addEventListener('fie:league-changing',()=>{++readerSerial;++renderSerial;E()?.clearDisclosures();});}
window.FIEReportsWorkspace=Object.freeze({VERSION:'editorial-p06',render,openDocument,openLeagueReport,fmt,markdown,enhanceSummary});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
